import{b as a,O as s,g as e,j as n}from"./chunks/framework.DSt9LnBW.js";const b=JSON.parse('{"title":"CSS选择器有哪些？哪些属性可以继承？","description":"选择器从标签、类、id 到后代、子代、伪类，权重各不相同。可继承的多半是文字相关属性，盒模型和定位一般不继承。能用类就别堆 id。","frontmatter":{"date":"2026-06-09T00:00:00.000Z","tags":["CSS","选择器"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/frontend/selectors-inheritance/index.md","filePath":"个人博客/前端/16.CSS选择器有哪些？哪些属性可以继承？.md","lastUpdated":1789442310000}'),d={name:"blog/frontend/selectors-inheritance/index.md"};function p(l,t,i,o,r,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="css选择器有哪些-哪些属性可以继承" tabindex="-1">CSS选择器有哪些？哪些属性可以继承？ <a class="header-anchor" href="#css选择器有哪些-哪些属性可以继承" aria-label="Permalink to &quot;CSS选择器有哪些？哪些属性可以继承？&quot;">​</a></h1><table tabindex="0"><thead><tr><th>选择器</th><th>作用</th><th>缺点</th><th>使用情况</th><th>用法</th></tr></thead><tbody><tr><td>标签选择器</td><td>可以选出所有相同的标签</td><td>不能差异化选择</td><td>较多</td><td><code>p{color:red;}</code></td></tr><tr><td>类选择器</td><td>可以选出1个或者多个标签</td><td>可以根据需求选择</td><td>非常多</td><td><code>.nav {color:red}</code></td></tr><tr><td>id选择器</td><td>一次只能选择1个标签</td><td>只能使用一次</td><td>不推荐使用</td><td><code>#nav {color:red}</code></td></tr><tr><td>通配符选择器</td><td>选择所有的标签</td><td>选择的太多，有部分不需要</td><td>不推荐使用功能</td><td><code>* {color:red}</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>后代选择器</th><th>用来选择元素后代</th><th>是选择所有的子孙后代</th><th>较多</th><th><code>.nav a</code></th></tr></thead><tbody><tr><td>子代选择器</td><td>选择最近一级元素</td><td>只选亲儿子</td><td>较少</td><td><code>.nav&gt;p</code></td></tr><tr><td>交集选择器</td><td>选择两个标签交集的部分</td><td>既是 又是</td><td>较少</td><td><code>p.one</code></td></tr><tr><td>并集选择器</td><td>选择某些相同样式的选择器</td><td>可以用于集体声明</td><td>较多</td><td><code>.nav,.header</code></td></tr><tr><td>链接伪类选择器</td><td>给链接更改状态</td><td></td><td>较多</td><td><code>a:hover</code><br><br>超链接伪类：<br><br><code>a:link</code>, 设置超链接基础样式<br><br><code>a:visited</code>, 设置超链接点击过的样式<br><br><code>a:hover</code>, 设置鼠标悬停在上方时的样式<br><br><code>a:active</code>, 设置鼠标点击中的样式</td></tr></tbody></table><h3 id="可继承的属性" tabindex="-1">可继承的属性 <a class="header-anchor" href="#可继承的属性" aria-label="Permalink to &quot;可继承的属性&quot;">​</a></h3><h4 id="字体" tabindex="-1">字体 <a class="header-anchor" href="#字体" aria-label="Permalink to &quot;字体&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>font：组合字体</span></span>
<span class="line"><span>font-family：规定元素的字体系列</span></span>
<span class="line"><span>font-weight：设置字体的粗细</span></span>
<span class="line"><span>font-size：设置字体的尺寸</span></span>
<span class="line"><span>font-style：定义字体的风格</span></span>
<span class="line"><span>font-variant：设置小型大写字母的字体显示文本，这意味着所有的小写字母均会被转换为大写，但是所有使用小型大写字体的字母与其余文本相比，其字体尺寸更小。</span></span>
<span class="line"><span>font-stretch：对当前的 font-family 进行伸缩变形。所有主流浏览器都不支持。</span></span>
<span class="line"><span>font-size-adjust：为某个元素规定一个 aspect 值，这样就可以保持首选字体的 x-height。</span></span></code></pre></div><h4 id="文本" tabindex="-1">文本 <a class="header-anchor" href="#文本" aria-label="Permalink to &quot;文本&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text-indent：文本缩进</span></span>
<span class="line"><span>text-align：文本水平对齐</span></span>
<span class="line"><span>line-height：行高</span></span>
<span class="line"><span>word-spacing：增加或减少单词间的空白（即字间隔）</span></span>
<span class="line"><span>letter-spacing：增加或减少字符间的空白（字符间距）</span></span>
<span class="line"><span>text-transform：控制文本大小写</span></span>
<span class="line"><span>direction：规定文本的书写方向</span></span>
<span class="line"><span>color：文本颜色</span></span></code></pre></div><h4 id="不常用" tabindex="-1">不常用 <a class="header-anchor" href="#不常用" aria-label="Permalink to &quot;不常用&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>元素可见性：visibility</span></span>
<span class="line"><span>表格布局属性：caption-side、border-collapse、border-spacing、empty-cells、table-layout</span></span>
<span class="line"><span>列表布局属性：list-style-type、list-style-image、list-style-position、list-style</span></span>
<span class="line"><span>生成内容属性：quotes</span></span>
<span class="line"><span>光标属性：cursor</span></span>
<span class="line"><span>页面样式属性：page、page-break-inside、windows、orphans</span></span>
<span class="line"><span>声音样式属性：speak、speak-punctuation、speak-numeral、speak-header、speech-rate、volume、voice-family、pitch、pitch-range、stress、richness、、azimuth、elevation</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>选择器从标签、类、id 到后代、子代、伪类，权重各不相同。可继承的多半是文字相关属性，盒模型和定位一般不继承。能用类就别堆 id。</p><div class="blog-refs"><p>参考资料</p><ul><li><a href="https://blog.csdn.net/weixin_43972437/article/details/127750792" target="_blank" rel="noreferrer">CSS 属性的继承</a></li></ul></div>`,13)])])}const u=a(d,[["render",p]]);export{b as __pageData,u as default};
